export const TURKEY_SIM_START = 1774234826000;
export const TURKEY_SIM_END   = 1774299599000;
export const TURKEY_CENTER    = [35.0, 39.0];
export const TURKEY_ZOOM      = 6;

function buildTurkeyEvents() {
  const jobs = TR_RAW_JOBS.map(j => ({
    id: 'job_' + j.id, type: 'job', province: j.st, customerProvince: j.cSt ?? j.st, timestamp: j.ts,
    customerLat: j.lat, customerLng: j.lng,
    proLat: j.pLat, proLng: j.pLng,
    serviceName: j.s, serviceCategory: j.c,
    proName: '', arcDuration: 1200, arcFadeDelay: 0,
  }));
  const quotes = TR_RAW_QUOTES.map(q => ({
    id: 'quote_' + q.id, type: 'quote', province: q.st, proProvince: q.pSt, timestamp: q.ts,
    customerLat: q.jLat, customerLng: q.jLng,
    proLat: q.pLat, proLng: q.pLng,
    serviceName: q.s, serviceCategory: q.c,
    arcDuration: 2000, arcFadeDelay: 2000,
  }));
  return [...jobs, ...quotes].sort((a, b) => a.timestamp - b.timestamp);
}

export const TURKEY_EVENTS = buildTurkeyEvents();